    AND ("cache_write_surcharge_estimated" IS NULL OR json_type("cache_write_surcharge_estimated") = 'NULL' OR (json_type("cache_write_surcharge_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("cache_write_surcharge_estimated" AS DOUBLE) IS NOT NULL))
    AND ("trim_saved_tokens_estimated" IS NULL OR json_type("trim_saved_tokens_estimated") = 'NULL' OR (json_type("trim_saved_tokens_estimated") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("trim_saved_tokens_estimated" AS BIGINT) IS NOT NULL))
    AND ("trim_saved_estimated" IS NULL OR json_type("trim_saved_estimated") = 'NULL' OR (json_type("trim_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("trim_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("trim_cost_estimated" IS NULL OR json_type("trim_cost_estimated") = 'NULL' OR (json_type("trim_cost_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("trim_cost_estimated" AS DOUBLE) IS NOT NULL))
    AND ("images_saved_tokens_estimated" IS NULL OR json_type("images_saved_tokens_estimated") = 'NULL' OR (json_type("images_saved_tokens_estimated") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("images_saved_tokens_estimated" AS BIGINT) IS NOT NULL))
    AND ("images_saved_estimated" IS NULL OR json_type("images_saved_estimated") = 'NULL' OR (json_type("images_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("images_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("images_cost_estimated" IS NULL OR json_type("images_cost_estimated") = 'NULL' OR (json_type("images_cost_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("images_cost_estimated" AS DOUBLE) IS NOT NULL))
    AND ("snapshots_saved_tokens_estimated" IS NULL OR json_type("snapshots_saved_tokens_estimated") = 'NULL' OR (json_type("snapshots_saved_tokens_estimated") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("snapshots_saved_tokens_estimated" AS BIGINT) IS NOT NULL))
    AND ("snapshots_saved_estimated" IS NULL OR json_type("snapshots_saved_estimated") = 'NULL' OR (json_type("snapshots_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("snapshots_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("snapshots_cost_estimated" IS NULL OR json_type("snapshots_cost_estimated") = 'NULL' OR (json_type("snapshots_cost_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("snapshots_cost_estimated" AS DOUBLE) IS NOT NULL))
    AND ("stabiliser_saved_estimated" IS NULL OR json_type("stabiliser_saved_estimated") = 'NULL' OR (json_type("stabiliser_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("stabiliser_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("warming_expected_saved_estimated" IS NULL OR json_type("warming_expected_saved_estimated") = 'NULL' OR (json_type("warming_expected_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("warming_expected_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("request_hash" IS NULL OR json_type("request_hash") = 'NULL' OR (json_type("request_hash") = 'VARCHAR'))
    AND ("cached_response" IS NULL OR json_type("cached_response") = 'NULL' OR (json_type("cached_response") = 'BOOLEAN'))
    AND ("response_cache_saved_estimated" IS NULL OR json_type("response_cache_saved_estimated") = 'NULL' OR (json_type("response_cache_saved_estimated") IN ('BIGINT', 'UBIGINT', 'DOUBLE') AND TRY_CAST("response_cache_saved_estimated" AS DOUBLE) IS NOT NULL))
    AND ("person" IS NULL OR json_type("person") = 'NULL' OR (json_type("person") = 'VARCHAR'))
    AND ("team" IS NULL OR json_type("team") = 'NULL' OR (json_type("team") = 'VARCHAR'))
    AND ("agent_version" IS NULL OR json_type("agent_version") = 'NULL' OR (json_type("agent_version") = 'VARCHAR'))
    AND ("ttft_ms" IS NULL OR json_type("ttft_ms") = 'NULL' OR (json_type("ttft_ms") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("ttft_ms" AS BIGINT) IS NOT NULL))
    AND ("upstream_ms" IS NULL OR json_type("upstream_ms") = 'NULL' OR (json_type("upstream_ms") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("upstream_ms" AS BIGINT) IS NOT NULL))
    AND ("error_class" IS NULL OR json_type("error_class") = 'NULL' OR (json_type("error_class") = 'VARCHAR'))
    AND ("attempts" IS NULL OR json_type("attempts") = 'NULL' OR (json_type("attempts") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("attempts" AS BIGINT) IS NOT NULL))
    AND ("first_choice" IS NULL OR json_type("first_choice") = 'NULL' OR (json_type("first_choice") = 'VARCHAR'))
    AND ("route_reason" IS NULL OR json_type("route_reason") = 'NULL' OR (json_type("route_reason") = 'VARCHAR'))
    AND ("auto_weight" IS NULL OR json_type("auto_weight") = 'NULL' OR (json_type("auto_weight") = 'VARCHAR'))
    AND ("auto_basis" IS NULL OR json_type("auto_basis") = 'NULL' OR (json_type("auto_basis") = 'VARCHAR'))
    AND ("cache_detail" IS NULL OR json_type("cache_detail") = 'NULL' OR (json_type("cache_detail") = 'VARCHAR'))
    AND ("tools_hash" IS NULL OR json_type("tools_hash") = 'NULL' OR (json_type("tools_hash") = 'VARCHAR'))
    AND ("system_hash" IS NULL OR json_type("system_hash") = 'NULL' OR (json_type("system_hash") = 'VARCHAR'))
    AND ("budget_scope" IS NULL OR json_type("budget_scope") = 'NULL' OR (json_type("budget_scope") = 'VARCHAR'))
    AND ("proxy_id" IS NULL OR json_type("proxy_id") = 'NULL' OR (json_type("proxy_id") = 'VARCHAR'))
    AND ("proxy_name" IS NULL OR json_type("proxy_name") = 'NULL' OR (json_type("proxy_name") = 'VARCHAR'))
    AND ("proxy_instance" IS NULL OR json_type("proxy_instance") = 'NULL' OR (json_type("proxy_instance") = 'VARCHAR'))
    AND ("origin_proxy" IS NULL OR json_type("origin_proxy") = 'NULL' OR (json_type("origin_proxy") = 'VARCHAR'))
    AND ("hops" IS NULL OR json_type("hops") = 'NULL' OR (json_type("hops") IN ('BIGINT', 'UBIGINT') AND TRY_CAST("hops" AS BIGINT) IS NOT NULL))
    AND ("via" IS NULL OR json_type("via") = 'NULL' OR (json_type("via") = 'VARCHAR'))
    AND ("account_source" IS NULL OR json_type("account_source") = 'NULL' OR (json_type("account_source") = 'VARCHAR'))
    AND ("record_id" IS NULL OR json_type("record_id") = 'NULL' OR (json_type("record_id") = 'VARCHAR'))
    AND ("request_id" IS NULL OR json_type("request_id") = 'NULL' OR (json_type("request_id") = 'VARCHAR'))
    AND ("reported_by" IS NULL OR json_type("reported_by") = 'NULL' OR (json_type("reported_by") = 'VARCHAR'))
    AND ("source" IS NULL OR json_type("source") = 'NULL' OR (json_type("source") = 'VARCHAR'))
    AND ("forwarded" IS NULL OR json_type("forwarded") = 'NULL' OR (json_type("forwarded") = 'BOOLEAN'))
)
WHERE "at" IS NOT NULL) s
WHERE (s."record_id" IS NULL OR NOT EXISTS (SELECT 1 FROM tgt.main.usage u WHERE u."record_id" = s."record_id" AND u."loaded_at" >= now() - INTERVAL '7 days'))
QUALIFY s."record_id" IS NULL OR row_number() OVER (PARTITION BY s."record_id" ORDER BY s."ingest_seq") = 1;
INSERT INTO tgt.main.events BY NAME
SELECT s.* EXCLUDE ("ingest_seq"), 'postgres:maple_events' AS "loaded_from", now() AS "loaded_at"
FROM (SELECT TRY_CAST("at" AS TIMESTAMPTZ) AS "at", NULLIF("kind", '') AS "kind", NULLIF("subject", '') AS "subject", NULLIF("level", '') AS "level", NULLIF("code", '') AS "code", NULLIF("value", '') AS "value", NULLIF("detail", '') AS "detail", "ingest_seq" FROM (SELECT json_extract_string("line", '$."at"') AS "at", json_extract_string("line", '$."kind"') AS "kind", json_extract_string("line", '$."subject"') AS "subject", json_extract_string("line", '$."level"') AS "level", json_extract_string("line", '$."code"') AS "code", json_extract_string("line", '$."value"') AS "value", json_extract_string("line", '$."detail"') AS "detail", "ingest_seq" FROM postgres_scan_pushdown(getenv('MAPLE_POSTGRES_DSN'), 'public', 'maple_events') WHERE json_valid("line") AND "ingest_seq" > getvariable('maple_w_events') AND "ingest_seq" <= getvariable('maple_hi_events')) WHERE TRY_CAST("at" AS TIMESTAMPTZ) IS NOT NULL AND NULLIF("kind", '') IS NOT NULL) s;
DELETE FROM tgt.main.maple_state WHERE "unit" IN ('source:postgres', 'postgres:maple_usage', 'postgres:maple_child_usage', 'postgres:maple_events');
INSERT INTO tgt.main.maple_state VALUES ('source:postgres', 'source', NULL, 0, now()), ('postgres:maple_usage', 'postgres', NULL, getvariable('maple_hi_usage'), now()), ('postgres:maple_child_usage', 'postgres', NULL, getvariable('maple_hi_child_usage'), now()), ('postgres:maple_events', 'postgres', NULL, getvariable('maple_hi_events'), now());
COMMIT;
SELECT 'x' AS maple_moved, getvariable('maple_hi_usage') - getvariable('maple_w_usage') AS usage_seq, getvariable('maple_hi_child_usage') - getvariable('maple_w_child_usage') AS child_seq, getvariable('maple_hi_events') - getvariable('maple_w_events') AS events_seq;
